// Enhanced application with proper error handling and input validation
// Security-focused implementation

const express = require('express');
const app = express();
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const validator = require('validator');

// Security middleware
app.use(helmet());

// Rate limiting configuration
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.'
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

// Apply rate limiting to all routes
app.use(apiLimiter);

// Body parser with size limits to prevent memory exhaustion
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
  verify: (req, res, buf, encoding) => {
    // Store body buffer for validation
    req.rawBody = buf;
  }
}));

app.use(express.urlencoded({
  limit: '10kb',
  extended: true
}));

// Comprehensive error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Log detailed error information (in production, use proper logging service)
  if (process.env.NODE_ENV === 'development') {
    res.status(err.status || 500).json({
      error: {
        message: err.message,
        ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
      }
    });
  } else {
    // Return generic error in production to avoid information disclosure
    res.status(err.status || 500).json({
      error: {
        message: 'An internal server error occurred',
        code: err.code || 'INTERNAL_ERROR'
      }
    });
  }
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: {
      message: 'Route not found',
      path: req.path
    }
  });
});

/**
 * Health check endpoint
 * No authentication required, but rate limited
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'healthy',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: process.env.NODE_ENV || 'development'
  });
});

/**
 * User list endpoint with strict validation
 */
app.get('/users', (req, res) => {
  try {
    // Basic query parameter validation
    const { page = 1, limit = 10 } = req.query;

    // Validate pagination parameters
    const pageNum = parseInt(page, 10);
    const limitNum = parseInt(limit, 10);

    if (isNaN(pageNum) || pageNum < 1 || pageNum > 1000) {
      return res.status(400).json({
        error: {
          message: 'Invalid page parameter',
          field: 'page',
          value: page
        }
      });
    }

    if (isNaN(limitNum) || limitNum < 1 || limitNum > 100) {
      return res.status(400).json({
        error: {
          message: 'Invalid limit parameter',
          field: 'limit',
          value: limit
        }
      });
    }

    // Simulated user data (in production, fetch from secure database)
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ];

    res.json({
      data: users,
      pagination: {
        page: pageNum,
        limit: Math.min(limitNum, users.length),
        total: users.length
      }
    });
  } catch (error) {
    next(error);
  }
});

// Create user endpoint validation example
app.post('/users', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string') {
      return res.status(400).json({
        error: {
          message: 'Name is required and must be a string',
          field: 'name'
        }
      });
    }

    if (name.trim().length < 2 || name.trim().length > 100) {
      return res.status(400).json({
        error: {
          message: 'Name must be between 2 and 100 characters',
          field: 'name'
        }
      });
    }

    if (!email || !validator.isEmail(email)) {
      return res.status(400).json({
        error: {
          message: 'Valid email is required',
          field: 'email'
        }
      });
    }

    // Additional email format validation
    if (!validator.isNotEmpty(email.trim())) {
      return res.status(400).json({
        error: {
          message: 'Email cannot be empty or whitespace only',
          field: 'email'
        }
      });
    }

    // Denormalized email for security (in production, store hashed)
    const user = {
      id: Math.floor(Math.random() * 10000),
      name: name.trim(),
      email: email.trim()
    };

    res.status(201).json({
      data: user,
      message: 'User created successfully'
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Graceful shutdown handler
 */
 const shutdown = () => {
  console.log('\nShutting down gracefully...');
  app.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
 };

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

// Error monitoring for development
if (process.env.NODE_ENV === 'development') {
  app.use((err, req, res, next) => {
    console.error('\n=== ERROR DETAILS ===');
    console.error('URL:', req.url);
    console.error('Method:', req.method);
    console.error('Headers:', req.headers);
    console.error('Body:', req.body || req.rawBody || 'N/A');
    console.error('Query:', req.query);
    console.error('IP:', req.ip);
    console.error('Error:', err);
    console.error('====================\n');
    next(err);
  });
}

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Access at: http://localhost:${PORT}`);
  console.log(`Health check at: http://localhost:${PORT}/health`);
});

module.exports = app;

