          error: {
            message: 'Invalid page parameter. Must be a positive integer',
            status: 400,
          },
        });
      }
    }

    // Return sanitized response
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
