// Secure Express Application with Comprehensive Error Handling and Input Validation
const express = require('express');
const helmet = require('helmet'); // Security headers middleware
const rateLimit = require('express-rate-limit');
const validator = require('validator'); // Input validation utility
const Joi = require('joi'); // Schema validation
const { body, param, validationResult } = express-validator; // Express validators

const app = express();

// =============================================================================
// SECURITY MIDDLEWARE
// =============================================================================

// Helmet: Sets security-related HTTP headers
app.use(helmet());

// Rate limiting: Prevent abuse and DDoS attacks
const limiter = rateLimit({
 windowMs: 15 * 60 * 1000, // 15 minutes
 max: 100, // Limit each IP to 100 requests per windowMs
 message: {
  error: 'Too many requests from this IP, please try again later.',
 },
 standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
 legacyHeaders: false, // Disable `X-RateLimit-*` headers
 skipSuccessfulRequests: true, // Only count failed requests
});
app.use('/api/', limiter);

// Body parsing with size limits (prevents buffer overflow attacks)
app.use(express.json({
 limit: '10kb', // Maximum payload size
}));
app.use(express.urlencoded({
 extended: true,
 limit: '10kb',
}));

// Security headers configuration
app.use((req, res, next) => {
 res.setHeader('X-Content-Type-Options', 'nosniff');
 res.setHeader('X-Frame-Options', 'DENY');
 res.setHeader('X-XSS-Protection', '1; mode=block');
 res.setHeader('Content-Security-Policy', "default-src 'self'; script-src 'self' 'unsafe-inline' https://trusted.cdn.com; object-src 'none';");
 res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
 next();
});

// Security middleware for body sanitization
app.use((req, res, next) => {
 // Sanitize body fields
 if (req.body) {
  Object.keys(req.body).forEach(key => {
   if (typeof req.body[key] === 'string') {
    // Remove potentially malicious characters
    req.body[key] = req.body[key].replace(/[<>]/g, '');
   }
  });
 }
 next();
});

// =============================================================================
// INPUT VALIDATION SCHEMAS
// =============================================================================

// User query validation schema
const getUserSchema = {
 query: Joi.object({
  page: Joi.number().integer().min(1).optional().default(1),
  limit: Joi.number().integer().min(1).max(100).optional().default(20),
 }),
};

// Health check validates it's a GET request only
const healthCheckSchema = {
 method: 'GET',
};

// =============================================================================
// VALIDATION ERROR HANDLER
// =============================================================================

const validateRequest = (req, res, next) => {
 const errors = validationResult(req);
 if (!errors.isEmpty()) {
  const errorObjects = errors.array().map(err => ({
   msg: err.msg,
   param: err.path.join('.'),
   location: err.type,
  }));
  return res.status(400).json({
   status: 'error',
   error: 'Validation Failed',
   validationErrors: errorObjects,
  });
 }
 next();
};

// =============================================================================
// ROUTES WITH PROPER VALIDATION
// =============================================================================

// Health check endpoint
app.get('/health', healthCheckSchema, (req, res) => {
 res.json({
  status: 'ok',
  timestamp: new Date().toISOString(),
  uptime: process.uptime(),
 });
});

// User endpoints with validation
app.get('/users', [
 query('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
 query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
 validateRequest,
], (req, res) => {
 return res.json([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
 ]);
});

// POST /users with comprehensive input validation (example)
app.post('/users', [
 body('name').trim()
  .notEmpty().withMessage('Name is required')
  .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
  .escape(), // Prevents XSS
 body('email').isEmail().normalizeEmail().withMessage('Invalid email address'),
], validateRequest, (req, res) => {
 // Process validated user data
 res.status(201).json({ message: 'User created successfully' });
});

// =============================================================================
// GLOBAL ERROR HANDLING
// =============================================================================

// Handle validation errors specifically
app.use((err, req, res, next) => {
 if (err instanceof ValidationError) {
  return res.status(400).json({
   status: 'error',
   error: 'Validation Error',
   message: err.message,
  });
 }
 next(err);
});

// Generic error handler
app.use((err, req, res, next) => {
 console.error('Error:', err);

 // In development, include error details
 if (process.env.NODE_ENV === 'development') {
  return res.status(500).json({
   status: 'error',
   error: 'Internal Server Error',
   message: err.message,
   stack: err.stack,
  });
 }

 // In production, return generic error message
 res.status(500).json({
  status: 'error',
  error: 'Internal Server Error',
  message: 'An unexpected error occurred',
 });
});

// 404 - Not Found Handler
app.use((req, res) => {
 res.status(404).json({
  status: 'error',
  error: 'Not Found',
  message: `Cannot ${req.method} ${req.path}`,
 });
});

// =============================================================================
// SECURITY CLOSURE: NEVER TRUST USER INPUT
// =============================================================================
/**
 * CRITICAL SECURITY NOTE:
 * 1. Never include sensitive data in error responses (especially in production)
 * 2. Always validate and sanitize all user input
 * 3. Use environment variables for configuration (not hardcoded secrets)
 * 4. Implement proper authentication and authorization
 * 5. Set NODE_ENV to 'production' before deploying
 * 6. Regularly update dependencies: `npm audit fix`
 * 7. Implement logging and monitoring
 * 8. Use HTTPS in production
 */

// =============================================================================
// START SERVER
// =============================================================================

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
 console.log(`Secure server running on http://localhost:${PORT}`);
 console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
 console.log(`Security headers enabled via Helmet`);
 console.log(`Rate limiting active`);
});

module.exports = app;

