# Security Review: app.js

## Current State Analysis

The current `app.js` is a minimal Express application with three endpoints:

1. `/health` - Health check endpoint
2. `/users` - Returns static user data as JSON

## Critical Security Issues Identified

### 1. Missing Input Validation ⚠️ HIGH
**Issue:** No validation on any incoming requests
**Security Impact:**
- No protection against injection attacks
- No sanitization of user input
- Accepts arbitrary inputs without validation

**Recommended Fix:**
```javascript
const express = require('express');
const validator = require('validator');
const rateLimit = require('express-rate-limit');
const helmet = require('helmet');
const xss = require('xss-clean');
const morgan = require('morgan');
const compression = require('compression');

const app = express();

// Security middleware
app.use(helmet()); // Set security HTTP headers
app.use(xss());    // Prevent XSS attacks
app.use(compression()); // Compress responses
app.use(morgan('combined')); // Logging with request duration

// Rate limiting - prevents brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use('/api', limiter);

// Input validation middleware
const validateQuery = (req, res, next) => {
  const allowedParams = ['search', 'page', 'limit', 'sort'];
  const invalidParams = Object.keys(req.query).filter(
    param => !allowedParams.includes(param)
  );

  if (invalidParams.length > 0) {
    return res.status(400).json({
      error: 'Invalid query parameters',
      invalidParams
    });
  }

  if (req.query.page && !Number.isInteger(parseInt(req.query.page))) {
    return res.status(400).json({ error: 'Page must be an integer' });
  }

  if (req.query.limit && (parseInt(req.query.limit) < 1 || parseInt(req.query.limit) > 100)) {
    return res.status(400).json({ error: 'Limit must be between 1 and 100' });
  }

  if (req.query.search && req.query.search.length > 100) {
    return res.status(400).json({ error: 'Search term too long' });
  }

  next();
};

// Health endpoint with validation
app.get('/health', validateQuery, (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint with validation
app.get('/users', validateQuery, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(err.status || 500).json({
    error: {
      message: err.message || 'Internal Server Error',
      ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
    }
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Endpoint not found' });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
  console.log(`Health check: http://localhost:${PORT}/health`);
});

module.exports = app;
```

### Detailed Improvements

## 1. Input Validation

### Validation Libraries to Consider:
```bash
npm install express-validator zod
```

### Implementation Suggestions:

**Option 1: express-validator (for route-level validation)**
```javascript
const { body, query, validationResult } = require('express-validator');

app.get('/users',
  query('page').optional().isInt({ min: 1 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  query('search').optional().trim().isLength({ max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe to access validated parameters
    const { search, page = 1, limit = 10 } = req.query;
    // Process logic...
  }
);
```

**Option 2: Zod (for request schema validation)**
```javascript
const { z } = require('zod');

const userQuerySchema = z.object({
  page: z.coerce.number().int().positive().optional(),
  limit: z.coerce.number().int().min(1).max(100).optional(),
  search: z.string().max(100).optional(),
});

app.get('/users', (req, res) => {
  try {
    const validatedQuery = userQuerySchema.parse(req.query);
    // Use validatedQuery for your logic
  } catch (error) {
    return res.status(400).json({ error: error.errors });
  }
});
```

## 2. Error Handling

### Current Issues:
❌ No centralized error handling
❌ No error logging
❌ Generic errors could expose implementation details
❌ No graceful degradation

### Improvements:

**Centralized Error Handling:**
```javascript
// Custom error classes
class AppError extends Error {
  constructor(statusCode, message) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

class ValidationError extends AppError {
  constructor(message) {
    super(400, message);
  }
}

class NotFoundError extends AppError {
  constructor(resource) {
    super(404, `${resource} not found`);
  }
}

// Error handler middleware
app.use((err, req, res, next) => {
  let error = { ...err };

  // Log error
  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method
  });

  // Handle specific error types
  if (err.name === 'CastError') {
    error = new ValidationError('Invalid ID format');
  }

  if (err.type === 'entity.parse.failed') {
    error = new ValidationError('Invalid JSON format');
  }

  // Send response
  res.status(error.statusCode || 500).json({
    success: false,
    error: {
      message: error.message,
      ...(process.env.NODE_ENV === 'development' && {
        stack: error.stack,
        details: error.details
      })
    }
  });
});
```

## 3. Security Middleware

### 1. Helmet.js - Security Headers
```bash
npm install helmet
```
Prevents common web vulnerabilities by setting various HTTP headers.

### 2. Rate Limiting
```bash
npm install express-rate-limit
```
Prevents brute force and DoS attacks.

### 3. XSS Protection
```bash
npm install xss-clean
```
Sanitizes user input to prevent Cross-Site Scripting.

### 4. Input Validation
```bash
npm install express-validator
```

## 4. Environment Security

### Add `.env` file:
```env
NODE_ENV=development
PORT=3000
JWT_SECRET=your-secret-key-here
# Never commit secrets!
```

