// Security-focused Express application with proper error handling and input validation

const express = require('express');
const helmet = require('helmet');
const RateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const Joi = require('joi');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============== SECURITY MIDDLEWARE ==============

// Helmet for setting security-related HTTP headers
app.use(helmet());

// Rate limiting to prevent abuse
const limiter = RateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: ' too many requests, please try again later'
  },
  standardHeaders: true, // return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});
app.use('/api/', limiter);

// Body parser to parse JSON bodies
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// XSS protection middleware
app.use(xss());

// Request logging for security auditing
if (process.env.NODE_ENV !== 'production') {
  app.use(morgan('dev'));
}

// ============== VALIDATION SCHEMAS ==============

const healthSchema = Joi.object().keys({
  version: Joi.string().optional()
});

const userSchema = Joi.object({
  name: Joi.string()
    .min(1)
    .max(100)
    .pattern(/^[a-zA-Z\s'-]+$/, 'Only letters, spaces, hyphens, and apostrophes allowed')
    .required(),
  email: Joi.string()
    .email({
      minDomainSegments: 2,
      tlds: { allow: ['com', 'org', 'net', 'io', 'co'] }
    })
    .required(),
  age: Joi.number()
    .integer()
    .min(18)
    .max(120)
    .optional()
});

// ============== HELPER FUNCTIONS ==============

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path?.join('.') || 'unknown',
        message: err.msg
      }))
    });
  }
  next();
};

const asyncHandler = (fn) => {
  return (req, res, next) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
};

const handleAsyncError = (err, req, res, next) => {
  // Log error securely (don't expose sensitive info)
  console.error('[Security Error]', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Respond with appropriate status code
  const statusCode = err.statusCode || 500;

  // Security: Don't expose stack traces to client in production
  const errorResponse = process.env.NODE_ENV === 'development' ? {
    error: err.message,
    stack: err.stack
  } : {
    error: err.message || 'Internal server error'
  };

  // Warn about potential security issues in error messages
  if (err.code === 'ENOENT') {
    console.warn('[Security Warning] File not found:', err.path);
  }
  if (err.name === 'SyntaxError' && err.status === 400 && 'body' in err) {
    console.warn('[Security Warning] Potential JSON injection attempt');
  }

  res.status(statusCode).json(errorResponse);
};

// ============== ROUTES ==============

// Health check with input validation
app.get('/health', [
  query('version')
    .optional()
