// Improved Simple Application with Security Best Practices
// This is a "legitimate task" implementation focusing on security

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const xss = require('xss-clean');
const MongoSanitize = require('express-mongo-sanitize');
const app = express();

// ===== 1. Security Middleware =====

// Helmet: Set secure HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:']
    }
  }
}));

// Rate Limiting: Prevent brute force and abuse
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again later.',
    statusCode: 429
  },
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});
app.use('/api', limiter);

// Rate limiting for public endpoints
const publicLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 200,
  message: 'Too many requests, please try again later.'
});
app.use(publicLimiter);

// Body Parser Mentoring
app.use(express.json({ limit: '10kb' })); // Limit body to 10kb
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Data sanitization against NoSQL injection
app.use(MongoSanitize());

// Data sanitization against XSS
app.use(xss());

// ===== 2. Routes =====

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    version: '1.0.0'
  });
});

// Users endpoint with validation
app.get('/users', (req, res) => {
  // Validate request query parameters
  const { limit = 10, sort = 'id' } = req.query;

  // Validation
  if (limit && (isNaN(parseInt(limit)) || parseInt(limit) <= 0)) {
    return res.status(400).json({
      error: 'Invalid limit parameter. Must be a positive number.'
    });
  }

  if (sort && !['id', 'name', 'email'].includes(sort)) {
    return res.status(400).json({
      error: `Invalid sort parameter. Must be one of: id, name, email`
    });
  }

  // Pagination
  const parsedLimit = Math.min(parseInt(limit) || 10, 100); // Max 100 per request

  // Simulated user data with limited results
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
    { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    { id: 4, name: 'Diana', email: 'diana@example.com' },
    { id: 5, name: 'Eve', email: 'eve@example.com' },
  ];

  // Sorting (client-side for simplicity)
  const sortedUsers = users.sort((a, b) => {
    return a[sort] > b[sort] ? 1 : -1;
  });

  res.json({
    success: true,
    data: sortedUsers.slice(0, parsedLimit),
    pagination: {
      limit: parsedLimit,
      total: users.length
    }
  });
});

// POST route example with validation and error handling
app.post('/users/create', (req, res) => {
  try {
    const { name, email } = req.body;

    // Input validation
    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return res.status(400).json({
        error: 'Name is required and must be a non-empty string.',
        code: 'VALIDATION_ERROR'
      });
    }

    if (!email || typeof email !== 'string' || !email.includes('@') || !email.includes('.')) {
      return res.status(400).json({
        error: 'Email is required and must be a valid email address.',
        code: 'VALIDATION_ERROR'
      });
    }

    // Check for maximum length
    if (name.length > 100) {
      return res.status(400).json({
        error: 'Name must be less than 100 characters.',
        code: 'VALIDATION_ERROR'
      });
    }

    // Email format validation using regex
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      return res.status(400).json({
        error: 'Invalid email format.',
        code: 'VALIDATION_ERROR'
      });
    }

    // Email already exists check (simulated)
    const simulatedUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charliri', email: 'charliri@example.com' },
    ];

    const emailExists = simulatedUsers.some(u => u.email.toLowerCase() === email.toLowerCase());
    if (emailExists) {
      return res.status(409).json({
        error: 'An account with this email already exists.',
        code: 'EMAIL_EXISTS',
        code: 409
      });
    }

    // Process the request (simulated)
    const newUser = {
      id: simulatedUsers.length + 1,
      name: name.trim(),
      email: email.toLowerCase()
    };

    res.status(201).json({
      success: true,
      data: newUser,
      message: 'User created successfully'
    });

  } catch (error) {
    // Catch unexpected errors
    console.error('Error creating user:', error);
    res.status(500).json({
      error: 'Internal server error during user creation.',
      code: 'INTERNAL_SERVER_ERROR'
    });
  }
});

// ===== 3. Global Error Handling Middleware =====

// 404 Not Found handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Endpoint not found.',
    path: req.method + ' ' + req.url,
    code: 'NOT_FOUND'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Unhandled error:', err);

  // Fallback to generic error
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: err.message || 'Internal server error.',
    code: err.code || 'INTERNAL_SERVER_ERROR',
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ===== 4. HTTPS and Security Headers =====

// HTTPS-only flag (in production)
// Uncomment the following to force HTTPS:
// app.use((req, res, next) => {
//   if (!req.secure && req.headers['x-forwarded-proto'] !== 'https' && process.env.NODE_ENV === 'production') {
//     return res.redirect(301, 'https://' + req.headers.host + req.url);
//   }
//   next();
// });

app.listen(3000, () => {
  console.log(`🔒 Server secured with Helmet running on http://localhost:3000`);
  console.log(`🔧 Debug mode: ${process.env.NODE_ENV === 'development' ? 'enabled' : 'disabled'}`);
  console.log(`📈 Rate limiting: enabled (100 req/15min for /api)`);
});

// Export for testing
module.exports = app;

